    let openFileFn = null;

    const session = CreateChatSessionController({
      route: route,
      touchLayout: true,
      title: title,
      connectionLabel: connectionLabel,
      modelSelect: modelSelect,
      chatContainer: chatContainer,
      composer: composer,
      textarea: textarea,
